import React, { useState, useRef, useEffect } from 'react';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizes = {
        sm: "h-7 text-[0.8rem]",
        md: "h-9 text-[1rem]",
        lg: "h-12 text-[1.3rem]"
    };

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                // FORCE RENDER OF 100%
                setProgress(100);
                onProgressChange?.(100);

                // Wait 60ms to let the user see the bar "hit the wall"
                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            defaultPrevented: false,
                            eventPhase: 3,
                            isTrusted: true,
                            nativeEvent: e.nativeEvent,
                            persist: () => {},
                            isDefaultPrevented: () => false,
                            isPropagationStopped: () => false,
                            stopPropagation: () => {}, 
                            preventDefault: () => {}   
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : '';

    return (
        <div className={`relative group ${widthClass} ${sizes[size]} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className="absolute inset-0 flex items-center justify-center z-20 skew-x-[-10deg] px-3 pointer-events-none">
                    <span className={`font-black text-white italic tracking-tight uppercase drop-shadow-md flex items-center gap-1 whitespace-nowrap transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {children}
                    </span>
                </div>
            </button>
        </div>
    );
};

import React from 'react';
import { useGame } from '../contexts/GameContext';
import { HexButton } from './ui/HexButton';
import { EnergyOrb } from './game/EnergyOrb';

export const ControlBar: React.FC = () => {
    const { 
        gameState, 
        isResolving, 
        isWaiting,
        currentEnergy, 
        isResultsHidden, 
        showUndoMenu, 
        actions, 
        setShowUndoMenu 
    } = useGame();

    const isInteractionDisabled = isResolving || isWaiting || gameState.phase !== 'planning';
    const isGameOver = gameState.winner !== null;

    return (
        <div className="h-10 px-2 pb-1 flex items-center justify-between relative bg-slate-950/50 border-t border-slate-800">
            {/* 
                ABSOLUTE CENTERED ORB 
                We hide this entirely when the game is over.
            */}
            {!isGameOver && (
                <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-40">
                    <EnergyOrb 
                        energy={currentEnergy}
                        showMenu={showUndoMenu}
                        disabled={isInteractionDisabled}
                        onClick={() => setShowUndoMenu(!showUndoMenu)}
                        onCloseMenu={() => setShowUndoMenu(false)}
                        onUndoAll={actions.handleUndoAll}
                    />
                </div>
            )}

            {isGameOver ? (
                /* GAME OVER CONTROLS: Left: Toggle, Center: Menu, Right: Retry */
                <div className="flex w-full items-center justify-between gap-2 h-full">
                    {/* LEFT: RESULTS TOGGLE */}
                    <div className="flex-1 flex justify-start">
                        <HexButton 
                            variant="secondary" 
                            size="sm" 
                            onClick={() => actions.toggleResults(!isResultsHidden)}
                        >
                            {isResultsHidden ? 'SHOW' : 'HIDE'}
                        </HexButton>
                    </div>

                    {/* CENTER: MENU */}
                    <div className="flex-1 flex justify-center">
                        <HexButton 
                            variant="secondary" 
                            size="sm" 
                            onClick={actions.handleExit}
                        >
                            MENU
                        </HexButton>
                    </div>

                    {/* RIGHT: PLAY AGAIN */}
                    <div className="flex-1 flex justify-end">
                        <HexButton 
                            variant="success" 
                            size="sm" 
                            onClick={actions.restartGame}
                        >
                            PLAY AGAIN
                        </HexButton>
                    </div>
                </div>
            ) : (
                /* GAMEPLAY CONTROLS */
                <>
                    {/* LEFT SIDE: RESIGN */}
                    <div className="flex-1 flex justify-start">
                        <HexButton 
                            variant="danger" 
                            size="sm" 
                            onClick={actions.handleResign} 
                            disabled={isResolving}
                        >
                            RESIGN
                        </HexButton>
                    </div>

                    {/* SPACER FOR ORB */}
                    <div className="w-12 h-10 flex-none" />

                    {/* RIGHT SIDE: END TURN */}
                    <div className="flex-1 flex justify-end">
                        <HexButton 
                            variant="primary" 
                            size="sm"
                            onClick={actions.handleEndTurn} 
                            disabled={isResolving || isWaiting}
                        >
                            {isResolving ? 'WAITING' : (isWaiting ? 'READY' : 'END TURN')}
                        </HexButton>
                    </div>
                </>
            )}
        </div>
    );
};

