import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { CardBoardView } from './card/CardBoardView';
import { CardFullArtView } from './card/CardFullArtView';
import { CardStandardView } from './card/CardStandardView';
import { useCardStats } from '../hooks/useCardStats';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  isPlayable?: boolean;
  isSelected?: boolean;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  variant?: 'default' | 'board';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
}

const CardComponent: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  variant = 'default', 
  hidden, 
  onPointerDown,
  isDragging
}) => {
  const sizeClasses = {
    xs: 'w-full aspect-[5/7] text-[0.45rem] rounded-sm border', 
    sm: 'w-13 aspect-[5/7] text-[0.55rem] rounded-md border-2',
    md: 'w-15 aspect-[5/7] text-[0.65rem] rounded-md border-2',
    lg: 'w-52 aspect-[5/7] text-lg rounded-xl border-4', 
  };
  const currentSizeClass = sizeClasses[size];

  if (hidden) {
    return (
      <div 
          role="presentation"
          className={`${currentSizeClass} bg-indigo-900 border-indigo-400 shadow-md flex items-center justify-center relative touch-none pointer-events-auto`}
          onClick={onClick}
          onPointerDown={onPointerDown}
      >
          <div className="w-1/3 h-1/3 rounded-full bg-indigo-500 animate-pulse"></div>
      </div>
    );
  }

  const { 
    currentDisplayPower, currentDisplayCost, 
    powerColor, costColor, def, borderColor 
  } = useCardStats(card);

  const opacityClass = isDragging ? 'opacity-0 pointer-events-none' : 'opacity-100';
  const cursorClass = onPointerDown || onClick ? 'cursor-grab active:cursor-grabbing' : '';
  const borderClass = size === 'xs' ? 'border' : (size === 'lg' ? 'border-4' : 'border-2');

  const sharedProps = {
    def, borderColor, borderClass, opacityClass, cursorClass, size,
    currentDisplayCost, currentDisplayPower, costColor, powerColor,
    onPointerDown, onClick
  };

  if (variant === 'board') {
    return <CardBoardView {...sharedProps} />;
  }

  if (size === 'lg') {
    return <CardFullArtView {...sharedProps} currentSizeClass={currentSizeClass} />;
  }

  return <CardStandardView {...sharedProps} currentSizeClass={currentSizeClass} />;
};

export const Card = React.memo(CardComponent, (prev, next) => {
    // Check primitive props first
    if (prev.size !== next.size || 
        prev.variant !== next.variant || 
        prev.hidden !== next.hidden || 
        prev.isDragging !== next.isDragging || 
        prev.isSelected !== next.isSelected || 
        prev.isPlayable !== next.isPlayable) return false;

    // Compare IDs
    const prevId = 'instanceId' in prev.card ? prev.card.instanceId : prev.card.id;
    const nextId = 'instanceId' in next.card ? next.card.instanceId : next.card.id;
    if (prevId !== nextId) return false;

    // For instances, check if stats have changed
    if ('instanceId' in prev.card && 'instanceId' in next.card) {
        return (
            prev.card.totalPower === next.card.totalPower &&
            prev.card.totalCost === next.card.totalCost &&
            prev.card.zone === next.card.zone &&
            prev.card.faceUp === next.card.faceUp
        );
    }

    return true; 
});

