const badgeConfig = {
    xs: { 
        dims: 'w-3.5 h-3.5', 
        text: 'text-[0.5rem]', 
        radiusTL: 'rounded-br-sm', 
        radiusTR: 'rounded-bl-sm' 
    },
    sm: { 
        dims: 'w-4.5 h-4.5', 
        text: 'text-[0.6rem]', 
        radiusTL: 'rounded-br-sm', 
        radiusTR: 'rounded-bl-sm' 
    },
    md: { 
        dims: 'w-5 h-5', 
        text: 'text-[0.7rem]', 
        radiusTL: 'rounded-br-md', 
        radiusTR: 'rounded-bl-md' 
    },
    lg: { 
        dims: 'w-9 h-9', 
        text: 'text-lg', 
        radiusTL: 'rounded-br-xl', 
        radiusTR: 'rounded-bl-xl' 
    },
};

export const CardBadge: React.FC<CardBadgeProps> = ({ value, type, size, colorClass, variant }) => {
    // Requirement: Do not display cost on board
    if (type === 'cost' && variant === 'board') return null;

    const b = badgeConfig[size];
    const position = type === 'cost' ? 'top-0 left-0' : 'top-0 right-0';
    const radius = type === 'cost' ? b.radiusTL : b.radiusTR;

    // Background colors: Energy = Blue, Power = Red
    const bgColor = type === 'cost' ? 'bg-blue-600' : 'bg-red-600';

    // Border Width Logic
    const w = size === 'lg' ? '2' : (size === 'md' ? '1' : '');
    const suffix = w ? `-${w}` : '';

    // Border Side Logic
    const borderStyle = type === 'cost' 
        ? `border-r${suffix} border-b${suffix}` 
        : `border-l${suffix} border-b${suffix}`;

    return (
      <div className={`absolute ${position} ${bgColor} ${colorClass} font-black ${radius} ${borderStyle} border-white/20 z-10 shadow-lg flex items-center justify-center leading-none ${b.dims} ${b.text}`}>
        {value}
      </div>
    );
};

import React from 'react';
import { StatModifier } from '../../types';

interface StatHistoryProps {
    modifiers: StatModifier[];
    type: 'cost' | 'power';
    side: 'left' | 'right';
}

export const StatHistory: React.FC<StatHistoryProps> = ({ modifiers, type, side }) => {

    const renderStatModifier = (m: StatModifier) => {
        const isBase = m.type === 'BASE';
        let valueColor = 'text-white';
        let sign = '';

        if (!isBase) {
            if (type === 'power') {
                // Power: +Green (Good), -Red (Bad)
                if (m.value > 0) { valueColor = 'text-green-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-red-400'; }
            } else {
                // Cost: +Red (Bad), -Green (Good)
                if (m.value > 0) { valueColor = 'text-red-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-green-400'; }
            }
        }

        return (
            <div className="flex justify-between items-center w-full mb-0.5 last:mb-0 bg-black/40 rounded-[2px] px-1 py-0.5">
                <span className="text-slate-400 text-[0.5rem] font-bold uppercase tracking-tight truncate max-w-[5rem]">
                    {m.source}
                </span>
                <span className={`font-black text-[0.7rem] leading-none ${valueColor}`}>
                    {sign}{m.value}
                </span>
            </div>
        );
    };

    // Positioning Classes: more tucked in towards the card to save horizontal space
    const positionClass = side === 'left' 
        ? "bottom-full right-[10%] origin-bottom-right" 
        : "bottom-full left-[10%] origin-bottom-left";

    return (
        <div className={`absolute ${positionClass} mb-2 w-32 animate-slide-up pointer-events-auto z-[60]`}>
             <div className="bg-slate-900/98 border border-slate-700/50 rounded-lg p-1.5 shadow-2xl flex flex-col max-h-32 overflow-y-auto">
                <div className="flex flex-col gap-0.5">
                    {modifiers.map((m, i) => (
                        <React.Fragment key={i}>
                            {renderStatModifier(m)}
                        </React.Fragment>
                    ))}
                </div>
             </div>
        </div>
    );
};

