export const getCardBorderColor = (tags: string[]): string => {
    if (!tags) return 'border-gray-600';
    if (tags.includes('OnReveal')) return 'border-yellow-500';
    if (tags.includes('Ongoing')) return 'border-blue-500';
    if (tags.includes('Destroy')) return 'border-red-500';
    if (tags.includes('Move')) return 'border-purple-500';
    if (tags.includes('Discard')) return 'border-slate-400';
    if (tags.includes('Summon')) return 'border-emerald-500';
    return 'border-gray-600';
};

export const getCardStats = (card: CardInstance | CardDefinition) => {
    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    if (!card) {
        return {
            basePower: 0,
            currentDisplayPower: 0,
            baseCost: 0,
            currentDisplayCost: 0,
            powerColor: 'text-white',
            costColor: 'text-white',
            def: { id: '', name: '', rarity: 'Common', baseCost: 0, basePower: 0, tags: [], baseText: '', effect: '', imageUrl: '' } as CardDefinition
        };
    }

    const def = isInstance(card) ? card.def : card;

    const basePower = def.basePower;
    const currentDisplayPower = isInstance(card) ? card.totalPower : basePower;

    const baseCost = def.baseCost;
    const currentDisplayCost = isInstance(card) ? card.totalCost : baseCost;

    const powerColor = currentDisplayPower > basePower 
        ? 'text-emerald-400' 
        : (currentDisplayPower < basePower ? 'text-red-400' : 'text-white');

    const costColor = currentDisplayCost < baseCost 
        ? 'text-emerald-400' 
        : (currentDisplayCost > baseCost ? 'text-red-400' : 'text-white');

    return {
        basePower,
        currentDisplayPower,
        baseCost,
        currentDisplayCost,
        powerColor,
        costColor,
        def
    };
};

import React from 'react';
import { StatModifier } from '../../types';

interface StatHistoryProps {
    modifiers: StatModifier[];
    type: 'cost' | 'power';
    side: 'left' | 'right';
}

export const StatHistory: React.FC<StatHistoryProps> = ({ modifiers, type, side }) => {

    const renderStatModifier = (m: StatModifier) => {
        const isBase = m.type === 'BASE';
        let valueColor = 'text-white';
        let sign = '';

        if (!isBase) {
            if (type === 'power') {
                // Power: +Emerald (Good), -Red (Bad)
                if (m.value > 0) { valueColor = 'text-emerald-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-red-400'; }
            } else {
                // Cost: +Red (Bad), -Emerald (Good)
                if (m.value > 0) { valueColor = 'text-red-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-emerald-400'; }
            }
        }

        return (
            <div className="flex justify-between items-center w-full mb-0.5 last:mb-0 bg-black/40 rounded-[2px] px-1 py-0.5">
                <span className="text-slate-400 text-[0.45rem] font-bold uppercase tracking-tight truncate max-w-[3.5rem]">
                    {m.source}
                </span>
                <span className={`font-black text-[0.6rem] leading-none ${valueColor}`}>
                    {sign}{m.value}
                </span>
            </div>
        );
    };

    // Correcting the side logic:
    // side="left" (Energy) -> left-0
    // side="right" (Power) -> right-0
    const positionClass = side === 'left' 
        ? "bottom-full left-0 origin-bottom-left" 
        : "bottom-full right-0 origin-bottom-right";

    return (
        <div className={`absolute ${positionClass} mb-2 w-24 animate-slide-up pointer-events-auto z-[60]`}>
             <div className="bg-slate-900/98 border border-slate-700/50 rounded-lg p-1 shadow-2xl flex flex-col max-h-32 overflow-y-auto">
                <div className="flex flex-col gap-0.5">
                    {modifiers.map((m, i) => (
                        <React.Fragment key={i}>
                            {renderStatModifier(m)}
                        </React.Fragment>
                    ))}
                </div>
             </div>
        </div>
    );
};

