import React from 'react';
import { CardDefinition } from '../../types';

interface DeckStatsProps {
    cards: CardDefinition[];
}

export const DeckStats: React.FC<DeckStatsProps> = ({ cards }) => {
    // Cost Distribution 1-6
    const distribution = Array.from({ length: 6 }).map((_, i) => {
        const cost = i + 1;
        const count = cards.filter(c => c.baseCost === cost).length;
        return { cost, count };
    });

    const maxCount = Math.max(...distribution.map(d => d.count), 1);
    const avgCost = cards.length > 0 
        ? (cards.reduce((acc, c) => acc + c.baseCost, 0) / cards.length).toFixed(1)
        : 0;

    return (
        <div className="flex items-end justify-between px-2 h-12 gap-6">
            <div className="flex-1 flex items-end justify-start gap-1 h-full max-w-[10rem]">
                {distribution.map(d => {
                    const height = (d.count / maxCount) * 100;
                    return (
                        <div key={d.cost} className="flex-1 flex flex-col items-center gap-1 group">
                            <div 
                                className={`w-full bg-indigo-500/30 rounded-t-sm transition-all duration-500 relative ${d.count > 0 ? 'bg-indigo-500' : 'bg-slate-800'}`}
                                style={{ height: `${Math.max(10, height)}%` }}
                            >
                                {d.count > 0 && <div className="absolute top-0 inset-x-0 h-0.5 bg-indigo-300 blur-[1px]"></div>}
                            </div>
                            <span className="text-[0.4rem] font-black text-slate-500">{d.cost}</span>
                        </div>
                    );
                })}
            </div>

            <div className="flex flex-col items-end justify-center mb-4">
                <div className="text-[0.55rem] font-black text-slate-500 uppercase tracking-widest leading-none mb-1">
                    AVG COST
                </div>
                <div className="text-xl font-black text-white italic leading-none tabular-nums">
                    {avgCost}
                </div>
            </div>

            <div className="flex flex-col items-end justify-center mb-4">
                <div className="text-[0.55rem] font-black text-slate-500 uppercase tracking-widest leading-none mb-1">
                    COUNT
                </div>
                <div className={`text-xl font-black italic leading-none tabular-nums ${cards.length === 12 ? 'text-emerald-400' : 'text-slate-400'}`}>
                    {cards.length}/12
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';

interface CollectionGridProps {
    ownedIds: string[];
    activeDeckIds: string[];
    onAdd: (id: string) => void;
    onRemove: (id: string) => void;
}

type SortOption = 'Cost' | 'Power' | 'Name';

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    ownedIds, activeDeckIds, onAdd, onRemove 
}) => {
    const [sortBy, setSortBy] = useState<SortOption>('Cost');

    const sortedCards = useMemo(() => {
        return [...CARDS].sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);

            // Primary Sort: Owned vs Not Owned
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            // Secondary Sort: User's Choice
            if (sortBy === 'Cost') return a.baseCost - b.baseCost;
            if (sortBy === 'Power') return b.basePower - a.basePower;
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, sortBy]);

    return (
        <div className="w-full h-full flex flex-col">
            {/* STICKY FILTERS */}
            <div className="bg-black/80 backdrop-blur-sm px-4 py-2 flex items-center justify-between border-b border-slate-900 z-10">
                <div className="flex gap-2">
                    {(['Cost', 'Power', 'Name'] as SortOption[]).map(opt => (
                        <button 
                            key={opt}
                            onClick={() => setSortBy(opt)}
                            className={`text-[0.5rem] font-black uppercase tracking-widest px-2 py-1 rounded border transition-all ${sortBy === opt ? 'bg-white text-black border-white' : 'text-slate-500 border-slate-800'}`}
                        >
                            {opt}
                        </button>
                    ))}
                </div>
                <div className="text-[0.5rem] font-black text-slate-600 uppercase tracking-widest">
                    {ownedIds.length} / {CARDS.length} Collected
                </div>
            </div>

            {/* SCROLLABLE GRID */}
            <div className="flex-1 overflow-y-auto p-4 pb-32">
                 <div className="grid grid-cols-4 gap-x-2 gap-y-4">
                     {sortedCards.map((def) => {
                         const isOwned = ownedIds.includes(def.id);
                         const inDeck = activeDeckIds.includes(def.id);

                         return (
                             <div 
                                key={def.id} 
                                className={`flex flex-col gap-1 transition-all duration-300 ${isOwned ? 'opacity-100' : 'opacity-40 grayscale pointer-events-none scale-90'}`}
                                onClick={() => isOwned && (inDeck ? onRemove(def.id) : onAdd(def.id))}
                             >
                                 <div className={`aspect-[5/7] rounded-md transition-all duration-300 ${inDeck ? 'ring-2 ring-indigo-500 ring-offset-2 ring-offset-black scale-105' : 'hover:scale-[1.02]'}`}>
                                     <Card 
                                        card={def} 
                                        size="xs" 
                                        variant="default" 
                                     />
                                 </div>
                                 <div className={`text-[0.45rem] font-black text-center truncate uppercase tracking-tighter ${inDeck ? 'text-indigo-400' : 'text-slate-500'}`}>
                                     {def.name}
                                 </div>
                             </div>
                         );
                     })}
                 </div>

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
};

