                     {sortedCards.map((def) => {
                         const isOwned = ownedIds.includes(def.id);
                         const inDeck = activeDeckIds.includes(def.id);
                         const isDragging = draggingCardId === def.id;

                         return (
                             <div 
                                key={def.id} 
                                className={`flex flex-col gap-1 transition-all duration-300 ${isOwned ? 'opacity-100' : 'opacity-40 grayscale pointer-events-none scale-90'} ${isDragging ? 'opacity-0' : ''}`}
