                             >
                                 <div className={`aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing ${inDeck ? 'ring-2 ring-indigo-500 ring-offset-2 ring-offset-black scale-105' : 'hover:scale-[1.02]'}`}>
