 * Finds a random valid lane and places the card there with a permanent power boost.
 */
export const WolverineEffect: OnRevealEffect = (state, source, context) => {
    let s = state;

    // 1. Apply the +2 Power Buff (Permanent)
    s = context.actions.modifyPower(s, source.instanceId, 2, 'Healing Factor');

    // 2. Determine potential lanes (0, 1, 2) and shuffle them for random pick
    const lanes = [0, 1, 2].sort(() => Math.random() - 0.5);

    // 3. Find the first lane with space
    const targetLaneIdx = lanes.find(idx => {
        const lane = s.lanes[idx];
        const slots = source.owner === 'p1' ? lane.p1Slots : lane.p2Slots;
        return slots.some(slot => slot === null);
    });

    if (targetLaneIdx !== undefined) {
        // 4. "Regenerate": Remove from current pile (Destroyed/Discarded) and place on board
        const playerState = s.players[source.owner];

        // Remove from piles
        playerState.destroyedPile = playerState.destroyedPile.filter(c => c.instanceId !== source.instanceId);
        playerState.discardPile = playerState.discardPile.filter(c => c.instanceId !== source.instanceId);

        // Update card state
        source.zone = 'BOARD';
        source.faceUp = true; // Always revealed when regenerating

        // Add to lane
        s = context.actions.addCardToLane(s, source, targetLaneIdx);

        // Visuals
        s = context.actions.playSfx(s, 'sfx_teleport_short');
        s.history.push(`${source.def.name} regenerated at Lane ${targetLaneIdx + 1}!`);
    } else {
        s.history.push(`${source.def.name} had no space to regenerate.`);
    }

    return s;
};

import { GameState, CardInstance } from '../types';
import { OnRevealEffect, EffectContext } from '../types';

// Import Effects from Card Files
import { GrenadierEffect } from '../cards/Grenadier';
import { ScoutEffect } from '../cards/Scout';
import { SaboteurEffect } from '../cards/Saboteur';
import { PortalMageEffect } from '../cards/PortalMage';
import { AnnihilatorEffect } from '../cards/Annihilator';
import { JumperEffect } from '../cards/Jumper';
import { VenomEffect, VenomEatEffect } from '../cards/Venom';
import { NovaEffect } from '../cards/Nova';
import { CarnageEffect, CarnageEatEffect } from '../cards/Carnage';
import { WolverineEffect } from '../cards/Wolverine';

// --- Registry ---

export const EFFECTS: Record<string, OnRevealEffect> = {
    'GrenadierEffect': GrenadierEffect,
    'ScoutEffect': ScoutEffect,
    'SaboteurEffect': SaboteurEffect,
    'AnnihilatorEffect': AnnihilatorEffect,
    'PortalMageEffect': PortalMageEffect,
    'JumperEffect': JumperEffect,
    'VenomEffect': VenomEffect,
    'VenomEatEffect': VenomEatEffect, // Sub-routine
    'NovaEffect': NovaEffect,
    'CarnageEffect': CarnageEffect,
    'CarnageEatEffect': CarnageEatEffect, // Sub-routine
    'WolverineEffect': WolverineEffect,
    // Add new cards here...
};

export const resolveEffect = (effectId: string, state: GameState, source: CardInstance, context: EffectContext): GameState => {
    const effectFn = EFFECTS[effectId];
    if (effectFn) {
        return effectFn(state, source, context);
    }
    return state;
};

import { GameState, EffectContext, ActionSet, SfxKey } from '../../types';
import { CARDS } from '../../constants';
import { cloneState, executeDestroy, addCardToHand, moveCard, addCardToLane, modifyPower, queueEvent } from '../mutations';
import { applyContinuousEffects } from '../statSystem';
import { findCardInState } from '../selectors';
import { resolveEffect } from '../effects';
import { queueAbility } from '../triggers';

// Internal helper to avoid circular dependency in ActionSet creation
const createActionSet = (): ActionSet => ({
    destroyCard: (s, id) => executeDestroy(s, id),
    addCardToHand: (s, c) => addCardToHand(s, c),
    moveCard: (s, id, t) => moveCard(s, id, t),
    addCardToLane: (s, c, l) => addCardToLane(s, c, l),
    modifyPower: (s, id, d, src) => modifyPower(s, id, d, src),
    recalcState: (s) => applyContinuousEffects(s),
    playSfx: (s, sfxId) => queueEvent(s, { type: 'SFX_PLAY', sfxId })
});

/**
 * Executes EXACTLY ONE task from the stack.
 * Used by the UI loop to provide visual pacing (wait between steps).
 */
export const stepExecutionQueue = (state: GameState): GameState => {
    let s = cloneState(state);

    if (s.executionQueue.length === 0) return s;

    // POP from the end (Top of Stack)
    const task = s.executionQueue.pop()!;

    switch (task.type) {
        case 'TRIGGER_ABILITY': {
            const lookup = findCardInState(s, task.sourceId);

            if (lookup) {
                const { card, laneIdx, slotIdx, owner, location } = lookup;

                // ZONE INTEGRITY CHECK
                const isDestroyTrigger = task.triggerTag === 'OnDestroy';
                const isDiscardTrigger = task.triggerTag === 'OnDiscard';

                let isValid = false;
                if (isDestroyTrigger) {
                    isValid = location === 'board' || location === 'destroyed';
                } else if (isDiscardTrigger) {
                    isValid = location === 'discard';
                } else {
                    isValid = location === 'board';
                }

                if (isValid) {
                    const ctx: EffectContext = {
                        player: owner,
                        laneIndex: laneIdx ?? 0, 
                        slotIndex: slotIdx ?? 0,
                        gameRegistry: CARDS,
                        actions: createActionSet() 
                    };

                    s = resolveEffect(card.def.effect, s, card, ctx);
                }
            }
            break;
        }

        case 'REVEAL_CARD': {
            const lookup = findCardInState(s, task.sourceId);

            // Only reveal if it's currently on the board
            if (lookup && lookup.location === 'board') {
                 const { card, laneIdx, slotIdx, owner } = lookup;

                 // Only reveal if currently hidden (idempotency)
                 if (!card.faceUp) {
                     card.faceUp = true;
                     s = applyContinuousEffects(s);

                     // Visuals
                     if (card.def.sfxOnReveal) {
                         s = queueEvent(s, { type: 'SFX_PLAY', sfxId: card.def.sfxOnReveal });
                     }
                     if (card.def.vfxOnReveal) {
                         s = queueEvent(s, { type: 'VFX_PLAY', vfxId: card.def.vfxOnReveal, laneIdx, slotIdx, playerId: owner });
                     }

                     // Trigger Ability
                     // This pushes the TRIGGER_ABILITY task to the stack, 
                     // so it executes immediately after this task finishes (LIFO).
                     if (card.def.tags.includes('OnReveal')) {
                         s = queueAbility(s, card, 'OnReveal');
                     }

                     s.history.push(`${card.def.name} was revealed (Summon).`);
                 }
            }
            break;
        }

        case 'EXECUTE_DISCARD': {
            const lookup = findCardInState(s, task.sourceId);
            if (lookup && lookup.location === 'hand') {
                    const { card, owner } = lookup;
                    const playerState = s.players[owner];

                    playerState.hand = playerState.hand.filter(c => c.instanceId !== task.sourceId);
                    playerState.discardPile.push(card);

                    card.zone = 'DISCARDED';
                    s = queueEvent(s, { type: 'SFX_PLAY', sfxId: 'sfx_ui_click' });
                    s.history.push(`${card.def.name} was discarded.`);

                    // Support for Wolverine / Swarm style discard triggers
                    if (card.def.tags.includes('OnDiscard')) {
                        s = queueAbility(s, card, 'OnDiscard');
                    }
            }
            break;
        }

        case 'RUN_EFFECT': {
            const lookup = findCardInState(s, task.sourceId);
            if (lookup) {
                const { card, laneIdx, slotIdx, owner } = lookup;
                const ctx: EffectContext = {
                    player: owner,
                    laneIndex: laneIdx ?? 0, 
                    slotIndex: slotIdx ?? 0,
                    gameRegistry: CARDS,
                    actions: createActionSet(),
                    params: task.params
                };
                s = resolveEffect(task.effectId, s, card, ctx);
            }
            break;
        }
    }

    return applyContinuousEffects(s);
};

/**
 * Drains the entire queue synchronously. 
 * Use this for fast-forwarding or non-visual logic (like start of game).
 */
export const processExecutionQueue = (state: GameState): GameState => {
    let s = state;
    let ops = 0;
    const MAX_OPS = 100;

    while (s.executionQueue.length > 0 && ops < MAX_OPS) {
        s = stepExecutionQueue(s);
        ops++;
    }
    return s;
};

import { CardInstance, StatModifier } from '../types';

export const addContinuousModifier = (card: CardInstance, modifier: StatModifier) => {
    card.powerModifiers.push(modifier);
    card.totalPower += modifier.value;
};

export const addContinuousCostModifier = (card: CardInstance, modifier: StatModifier) => {
    card.costModifiers.push(modifier);
    card.totalCost = Math.max(0, card.totalCost + modifier.value);
};

export const resetContinuousStats = (card: CardInstance) => {
    // 1. Filter out CONTINUOUS modifiers
    card.powerModifiers = card.powerModifiers.filter(m => m.type !== 'CONTINUOUS');
    card.costModifiers = card.costModifiers.filter(m => m.type !== 'CONTINUOUS');

    // 2. Re-sum to get Current (Base + Permanent)
    const currentPower = card.powerModifiers.reduce((sum, m) => sum + m.value, 0);
    const currentCost = card.costModifiers.reduce((sum, m) => sum + m.value, 0);

    card.currentPower = currentPower;
    card.currentCost = currentCost;

    // 3. Reset Total to Current (baseline before continuous are re-added)
    card.totalPower = currentPower;
    card.totalCost = currentCost;
};

import { GameState, CardInstance } from '../types';
import { ONGOING_EFFECTS } from './ongoingEffects';
import { resetContinuousStats, addContinuousModifier } from './statHelpers';

// --- Continuous Effects Engine ---

export const applyContinuousEffects = (state: GameState): GameState => {
  // Note: This mutates the provided state object (which should be a clone or draft)

  // 1. Collect all cards that can have stats (Hand + Board)
  const allCards = [
      ...state.players.p1.hand, ...state.players.p2.hand,
      ...state.lanes.flatMap(l => [...l.p1Slots, ...l.p2Slots])
  ];

  // 2. Reset totals to Base+Permanent
  allCards.forEach(card => {
      if (!card) return;
      resetContinuousStats(card);
  });

  // 3. Apply Location Effects (Layer 1) - Only applies to board
  state.lanes.forEach(lane => {
      [...lane.p1Slots, ...lane.p2Slots].forEach(card => {
          if (!card) return;

          if (lane.location.def.effect === 'PowerPlantEffect') {
             addContinuousModifier(card, { source: lane.location.def.name, value: 1, type: 'CONTINUOUS' });
          }
      });
  });

  // 4. Apply Ongoing Effects (Layer 2)
  const runEffect = (source: CardInstance, lIdx: number, sIdx: number) => {
      if (source.def.tags.includes('Ongoing')) {
          const effectFn = ONGOING_EFFECTS[source.def.effect];
          if (effectFn) {
              effectFn(state, lIdx, sIdx, source);
          }
      }
  };

  // Process Board (Must be faceUp)
  state.lanes.forEach((lane, laneIdx) => {
     lane.p1Slots.forEach((c, i) => c && c.faceUp && runEffect(c, laneIdx, i));
     lane.p2Slots.forEach((c, i) => c && c.faceUp && runEffect(c, laneIdx, i));
  });

  // Process Hands (Passive cost/power mods work in hand)
  state.players.p1.hand.forEach(c => runEffect(c, -1, -1));
  state.players.p2.hand.forEach(c => runEffect(c, -1, -1));

  return state;
};

