import React, { useState, useMemo } from 'react';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

export const DeckSelector: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const [flippedId, setFlippedId] = useState<number | null>(null);

    const handleDeckClick = (id: number) => {
        if (activeDeckId === id) {
            // Toggle flip if already active
            setFlippedId(flippedId === id ? null : id);
        } else {
            // Select new deck and ensure no flip is active
            onSelectDeck(id);
            setFlippedId(null);
        }
    };

    const getStats = (deckId: number) => {
        const cardIds = user.decks[deckId] || [];
        if (cardIds.length === 0) return { avgCost: 0, avgPower: 0, count: 0 };

        const deckCards = cardIds.map(id => CARDS.find(c => c.id === id)).filter(Boolean);
        const totalCost = deckCards.reduce((acc, c) => acc + (c?.baseCost || 0), 0);
        const totalPower = deckCards.reduce((acc, c) => acc + (c?.basePower || 0), 0);

        return {
            avgCost: (totalCost / deckCards.length).toFixed(1),
            avgPower: (totalPower / deckCards.length).toFixed(1),
            count: deckCards.length
        };
    };

    return (
        <div className="w-full flex overflow-x-auto py-0.5 px-3 gap-2 shrink-0 scrollbar-hide perspective-1000">
            {[1, 2, 3].map(i => {
                const isSelected = activeDeckId === i;
                const isFlipped = flippedId === i && isSelected;
                const stats = getStats(i);
                const deckName = user.deckNames[i] || 'UNTITLED';
                const isIncomplete = stats.count < 12;

                return (
                    <div 
                        key={i} 
                        className="min-w-[7rem] h-10 relative cursor-pointer"
                        onClick={() => handleDeckClick(i)}
                    >
                        <div className={`
                            w-full h-full relative transition-transform duration-500 transform-style-3d
                            ${isFlipped ? 'rotate-y-180' : ''}
                        `}>
                            {/* FRONT: DECK NAME */}
                            <div className={`
                                absolute inset-0 backface-hidden flex flex-col justify-center px-1.5 py-0.5 rounded-lg border transition-all
                                ${isSelected ? 'bg-indigo-600 border-indigo-400 shadow-lg' : 'bg-slate-800 border-slate-700'}
                            `}>
                                <div className="flex items-center justify-between w-full mb-0.5">
                                    <div className="text-[0.4rem] font-black text-indigo-200 uppercase tracking-widest opacity-60">DECK {i}</div>
                                    {isIncomplete && (
                                        <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />
                                    )}
                                </div>
                                <div className="text-[0.55rem] font-black text-white truncate text-left tracking-tight uppercase">
                                    {deckName}
                                </div>
                            </div>

                            {/* BACK: DECK STATS */}
                            <div className={`
                                absolute inset-0 backface-hidden rotate-y-180 flex items-center justify-around px-1.5 rounded-lg border border-indigo-300 bg-indigo-800 shadow-xl
                            `}>
                                <div className="flex flex-col items-center">
                                    <span className="text-[0.35rem] font-black text-indigo-200 uppercase leading-none mb-1">Cost</span>
                                    <span className="text-xs font-black text-white italic">{stats.avgCost}</span>
                                </div>
                                <div className="w-px h-6 bg-white/20" />
                                <div className="flex flex-col items-center">
                                    <span className="text-[0.35rem] font-black text-indigo-200 uppercase leading-none mb-1">Power</span>
                                    <span className="text-xs font-black text-white italic">{stats.avgPower}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                );
            })}

            <style>{`
                .perspective-1000 { perspective: 1000px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .rotate-y-180 { transform: rotateY(180deg); }
            `}</style>
        </div>
    );
};

import React, { useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';

interface CollectionGridProps {
    ownedIds: string[];
    activeDeckIds: string[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition) => void;
}

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    ownedIds, activeDeckIds, draggingCardId, onPointerDown 
}) => {
    const { collectionSort, collectionFilterSearch, collectionFilterTags } = useUser();

    const filteredAndSortedCards = useMemo(() => {
        let results = [...CARDS];

        if (collectionFilterSearch) {
            const query = collectionFilterSearch.toLowerCase();
            results = results.filter(c => 
                c.name.toLowerCase().includes(query) || 
                c.baseText.toLowerCase().includes(query)
            );
        }

        if (collectionFilterTags.length > 0) {
            results = results.filter(c => {
                return collectionFilterTags.some(tag => {
                    if (tag === 'None') return c.tags.length === 0;
                    return c.tags.includes(tag);
                });
            });
        }

        return results.sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            if (collectionSort === 'Cost') return a.baseCost - b.baseCost;
            if (collectionSort === 'Power') return b.basePower - a.basePower;
            if (collectionSort === 'Newest') {
                const aIdx = CARDS.findIndex(c => c.id === a.id);
                const bIdx = CARDS.findIndex(c => c.id === b.id);
                return bIdx - aIdx;
            }
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, collectionSort, collectionFilterSearch, collectionFilterTags]);

    return (
        <div className="w-full h-full flex flex-col">
            <div className="flex-1 overflow-y-auto p-4 pb-32">
                 {filteredAndSortedCards.length === 0 ? (
                     <div className="w-full py-20 flex flex-col items-center justify-center text-slate-700">
                         <svg className="w-12 h-12 mb-2 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">No matching cards</span>
                     </div>
                 ) : (
                     <div className="grid grid-cols-4 gap-x-2 gap-y-3">
                         {filteredAndSortedCards.map((def) => {
                             const isOwned = ownedIds.includes(def.id);
                             const inDeck = activeDeckIds.includes(def.id);
                             const isDragging = draggingCardId === def.id;

                             return (
                                 <div 
                                    key={def.id} 
                                    className={`relative transition-all duration-300 rounded-md ${isOwned ? 'opacity-100' : 'opacity-40 grayscale pointer-events-none scale-90'} ${isDragging ? 'opacity-0' : ''}`}
                                    onPointerDown={(e) => isOwned && onPointerDown(e, def)}
                                 >
                                     <div className={`aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing ${inDeck ? 'scale-105' : 'hover:scale-[1.02]'}`}>
                                         <Card 
                                            card={def} 
                                            size="xs" 
                                            variant="default" 
                                         />
                                     </div>
                                 </div>
                             );
                         })}
                     </div>
                 )}

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
};

