import React, { createContext, useContext, useState, ReactNode, useEffect, useCallback, useMemo } from 'react';
import { UserProfile, StoreData, CardDefinition, CardInstance, LocationDefinition, CardRarity } from '../types';
import { audio } from '../services/audio';
import { api } from '../services/api';
import { CARDS } from '../constants';
import { generateInstanceId } from '../utils/id';

export type CollectionSortOption = 'Cost' | 'Power' | 'Name' | 'Newest';

interface UserContextType {
    user: UserProfile;
    // Store State
    storeData: StoreData | null;
    isStoreLoading: boolean;
    storeScrollTarget: string | null;
    setStoreScrollTarget: (id: string | null) => void;
    // Inspect State
    inspectingCard: CardInstance | CardDefinition | null;
    inspectingLocation: LocationDefinition | null;
    inspectingCurrency: { type: 'gold' | 'credits', amount: number } | null;
    // Collection UI State
    collectionSort: CollectionSortOption;
    setCollectionSort: (s: CollectionSortOption) => void;
    collectionFilterSearch: string;
    setCollectionFilterSearch: (s: string) => void;
    collectionFilterTags: string[];
    toggleCollectionFilterTag: (tag: string) => void;
    // Actions
    addCredits: (amount: number) => void;
    spendCredits: (amount: number) => boolean;
    addGold: (amount: number) => void;
    spendGold: (amount: number) => boolean;
    setActiveDeck: (id: number) => Promise<void>;
    updateDeck: (deckId: number, cardIds: string[]) => void;
    upgradeCard: (cardId: string) => boolean;
    processPurchase: (offerId: string) => Promise<boolean>;
    syncStore: () => Promise<void>;
    // Inspector Methods
    inspect: (item: CardInstance | CardDefinition | LocationDefinition | { type: 'gold' | 'credits', amount: number } | null) => void;
    closeInspector: () => void;
    // Derived
    activeDeck: string[];
}

const INITIAL_USER: UserProfile = {
    id: 'u1',
    username: 'Commander',
    level: 42,
    credits: 1750,
    gold: 3035,
    activeDeckId: 1,
    avatarId: 'avatar_01',
    purchasedOfferIds: [],
    lastClaimedDates: {},
    collection: [...CARDS.map(c => c.id).slice(0, 10), 'c13', 'c14'], // Start with 10 + Carnage/Wolverine
    decks: {
        1: [...CARDS.map(c => c.id).slice(0, 10), 'c13', 'c14'], // Deck 1 also gets them
        2: [],
        3: []
    },
    deckNames: {
        1: 'ASSAULT',
        2: 'CONTROL',
        3: 'UNTITLED'
    },
    cardRarities: {}
};

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<UserProfile>(INITIAL_USER);

    // Global Store State
    const [storeData, setStoreData] = useState<StoreData | null>(null);
    const [isStoreLoading, setIsStoreLoading] = useState(false);
    const [storeScrollTarget, setStoreScrollTarget] = useState<string | null>(null);

    // Global Inspector State
    const [inspectingCard, setInspectingCard] = useState<CardInstance | CardDefinition | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);

    // Collection UI State
    const [collectionSort, setCollectionSort] = useState<CollectionSortOption>('Cost');
    const [collectionFilterSearch, setCollectionFilterSearch] = useState('');
    const [collectionFilterTags, setCollectionFilterTags] = useState<string[]>([]);

    const toggleCollectionFilterTag = (tag: string) => {
        setCollectionFilterTags(prev => 
            prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]
        );
    };

    // --- Actions ---

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    useEffect(() => {
        syncStore(true);
        let timeout: any;
        const poll = () => {
            const delay = (storeData?.refreshHintSeconds || 60) * 1000;
            timeout = setTimeout(async () => {
                await syncStore();
                poll();
            }, delay);
        };
        poll();
        return () => clearTimeout(timeout);
    }, [user.id, syncStore]);

    const inspect = (item: any) => {
        if (!item) return; 
        audio.playUiClick();

        if ('type' in item && (item.type === 'gold' || item.type === 'credits')) {
            setInspectingCurrency(item);
            setInspectingCard(null);
            setInspectingLocation(null);
        } 
        else if (('instanceId' in item) || ('basePower' in item) || ('definitionId' in item)) {
            setInspectingCard(item);
            setInspectingLocation(null);
            setInspectingCurrency(null);
        } 
        else if ('description' in item) {
            setInspectingLocation(item);
            setInspectingCard(null);
            setInspectingCurrency(null);
        }
    };

    const closeInspector = () => {
        setInspectingCard(null);
        setInspectingLocation(null);
        setInspectingCurrency(null);
    };

    const addCredits = (amount: number) => {
        setUser(prev => ({ ...prev, credits: prev.credits + amount }));
    };

    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) {
            setUser(prev => ({ ...prev, credits: prev.credits - amount }));
            return true;
        }
        return false;
    };

    const addGold = (amount: number) => {
        setUser(prev => ({ ...prev, gold: prev.gold + amount }));
    };

    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) {
            setUser(prev => ({ ...prev, gold: prev.gold - amount }));
            return true;
        }
        return false;
    };

    const setActiveDeck = async (id: number) => {
        audio.playUiClick();
        try {
            const updatedUser = await api.updateActiveDeck(user, id);
            setUser(updatedUser);
        } catch (e) {
            console.error("Failed to update active deck on server:", e);
        }
    };

    const updateDeck = (deckId: number, cardIds: string[]) => {
        setUser(prev => ({
            ...prev,
            decks: { ...prev.decks, [deckId]: cardIds }
        }));
    };

    const upgradeCard = (cardId: string): boolean => {
        const currentRarity = user.cardRarities[cardId] || "Common";
        const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
        const currentIndex = rarityPath.indexOf(currentRarity);

        if (currentIndex === -1 || currentIndex === rarityPath.length - 1) return false;

        const nextRarity = rarityPath[currentIndex + 1];
        const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
        const cost = costMap[nextRarity];

        if (user.credits >= cost) {
            setUser(prev => ({
                ...prev,
                credits: prev.credits - cost,
                level: prev.level + (currentIndex + 1), // Gain level on upgrade
                cardRarities: { ...prev.cardRarities, [cardId]: nextRarity }
            }));
            audio.play('sfx_victory');
            return true;
        }
        return false;
    };

    const processPurchase = async (offerId: string): Promise<boolean> => {
        const transactionId = `txn_${generateInstanceId()}`;
        try {
            const response = await api.purchaseOffer(user, offerId, transactionId);
            if (response.success && response.updatedProfile) {
                audio.play('sfx_victory');
                setUser(response.updatedProfile);
                return true;
            } else {
                audio.play('sfx_ui_hover');
                return false;
            }
        } catch (err) {
            console.error("Network Exception:", err);
            return false;
        }
    };

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, 
            storeData,
            isStoreLoading,
            storeScrollTarget,
            setStoreScrollTarget,
            inspectingCard, 
            inspectingLocation, 
            inspectingCurrency,
            collectionSort,
            setCollectionSort,
            collectionFilterSearch,
            setCollectionFilterSearch,
            collectionFilterTags,
            toggleCollectionFilterTag,
            addCredits, 
            spendCredits, 
            addGold, 
            spendGold, 
            setActiveDeck, 
            updateDeck,
            upgradeCard,
            processPurchase,
            syncStore,
            inspect,
            closeInspector,
            activeDeck
        }}>
            {children}
        </UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

import React, { useCallback, useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { DeckSelector } from '../deck/DeckSelector';
import { CollectionGrid } from '../deck/CollectionGrid';
import { DeckVault } from '../deck/DeckVault';
