// Added React import to resolve namespace error for React.PointerEvent
import React, { useState, useCallback, useRef, useEffect } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
    card: CardDefinition;
    origin: 'archive' | 'vault';
    startPos: { x: number; y: number };
    currentPos: { x: number; y: number };
    offset: { x: number; y: number };
    rect: DOMRect;
    active: boolean;
}

interface UseCollectionDragProps {
    onAdd: (id: string) => void;
    onRemove: (id: string) => void;
}

export const useCollectionDrag = ({ onAdd, onRemove }: UseCollectionDragProps) => {
    const { inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);
    const hasMovedRef = useRef(false);
    const pressTimerRef = useRef<number | null>(null);

    const handlePointerDown = useCallback((
        e: React.PointerEvent,
        card: CardDefinition,
        origin: 'archive' | 'vault'
    ) => {
        // Prevent right-click from initiating drag
        if (e.button !== 0) return;

        hasMovedRef.current = false;
        if (pressTimerRef.current) clearTimeout(pressTimerRef.current);

        const target = e.currentTarget as HTMLElement;
        const rect = target.getBoundingClientRect();

        setDragState({
            card,
            origin,
            startPos: { x: e.clientX, y: e.clientY },
            currentPos: { x: e.clientX, y: e.clientY },
            offset: { x: e.clientX - rect.left, y: e.clientY - rect.top },
            rect,
            active: false
        });
    }, []);

    useEffect(() => {
        if (!dragState) return;

        if (!dragState.active && pressTimerRef.current === null) {
            pressTimerRef.current = window.setTimeout(() => {
                hasMovedRef.current = true;
                setDragState(prev => prev ? { ...prev, active: true } : null);
                pressTimerRef.current = null;
            }, 250);
        }

        const handleMove = (e: PointerEvent) => {
            if (!dragState) return;

            // If drag is confirmed active, prevent default browser actions like scrolling.
            if (dragState.active) {
                e.preventDefault();
                hasMovedRef.current = true; 
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
                return;
            }

            // Before drag is active, check for scroll gesture.
            const dist = Math.sqrt(
                Math.pow(e.clientX - dragState.startPos.x, 2) + 
                Math.pow(e.clientY - dragState.startPos.y, 2)
            );

            if (pressTimerRef.current !== null && dist > 10) {
                // It's a scroll, not a drag. Clear timer and abort.
                // The browser will handle the scroll event because we haven't called preventDefault yet.
                clearTimeout(pressTimerRef.current);
                pressTimerRef.current = null;
                setDragState(null);
                return;
            }
        };

        const handleUp = (e: PointerEvent) => {
            if (pressTimerRef.current) {
                clearTimeout(pressTimerRef.current);
                pressTimerRef.current = null;
            }

            if (!dragState) return;

            if (!hasMovedRef.current) {
                inspect(dragState.card);
            } else if (dragState.active) {
                // Only perform drop logic if dragging was active
                const elements = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = elements.find(el => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = elements.find(el => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !vaultZone)) {
                    onRemove(dragState.card.id);
                }
            }

            setDragState(null);
        };

        // Use passive: false to allow preventDefault to work.
        window.addEventListener('pointermove', handleMove, { passive: false });
        window.addEventListener('pointerup', handleUp);
        window.addEventListener('pointercancel', handleUp);

        return () => {
            window.removeEventListener('pointermove', handleMove);
            window.removeEventListener('pointerup', handleUp);
            window.removeEventListener('pointercancel', handleUp);
            if (pressTimerRef.current) {
                clearTimeout(pressTimerRef.current);
                pressTimerRef.current = null;
            }
        };
    }, [dragState, inspect, onAdd, onRemove]);

    return {
        dragState,
        handlePointerDown
    };
};

// Added React import to resolve namespace error for React.PointerEvent
import React, { useState, useCallback, useRef, useEffect } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
    card: CardDefinition;
    origin: 'archive' | 'vault';
    startPos: { x: number; y: number };
    currentPos: { x: number; y: number };
    offset: { x: number; y: number };
    rect: DOMRect;
    active: boolean;
}

interface UseCollectionDragProps {
    onAdd: (id: string) => void;
    onRemove: (id: string) => void;
}

export const useCollectionDrag = ({ onAdd, onRemove }: UseCollectionDragProps) => {
    const { inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);
    const hasMovedRef = useRef(false);

    const handlePointerDown = useCallback((
        e: React.PointerEvent,
        card: CardDefinition,
        origin: 'archive' | 'vault'
    ) => {
        // Prevent right-click from initiating drag
        if (e.button !== 0) return;

        // Explicitly disable browser scrolling to handle drag gesture
        document.body.classList.add('no-scroll');
        hasMovedRef.current = false;

        const target = e.currentTarget as HTMLElement;
        const rect = target.getBoundingClientRect();

        setDragState({
            card,
            origin,
            startPos: { x: e.clientX, y: e.clientY },
            currentPos: { x: e.clientX, y: e.clientY },
            offset: { x: e.clientX - rect.left, y: e.clientY - rect.top },
            rect,
            active: false
        });
    }, []);

    useEffect(() => {
        if (!dragState) return;

        const handleMove = (e: PointerEvent) => {
            if (!dragState) return;

            // Check for movement threshold to initiate the "active" drag state
            const dist = Math.sqrt(
                Math.pow(e.clientX - dragState.startPos.x, 2) + 
                Math.pow(e.clientY - dragState.startPos.y, 2)
            );

            // If user moves more than 5px, we consider it a drag
            if (!hasMovedRef.current && dist > 5) {
                hasMovedRef.current = true;
            }

            // Only update position and set active state if there's been movement
            if (hasMovedRef.current) {
                setDragState(prev => prev ? { 
                    ...prev, 
                    active: true, // "active" now means visually dragging
                    currentPos: { x: e.clientX, y: e.clientY } 
                } : null);
            }
        };

        const handleUp = (e: PointerEvent) => {
            // Always re-enable scrolling when the gesture ends
            document.body.classList.remove('no-scroll');

            if (!dragState) return;

            if (!hasMovedRef.current) {
                // No movement means it was a tap.
                inspect(dragState.card);
            } else if (dragState.active) {
                // Movement occurred and drag was active, handle drop.
                const elements = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = elements.find(el => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = elements.find(el => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !vaultZone)) {
                    onRemove(dragState.card.id);
                }
            }

            setDragState(null);
        };

        window.addEventListener('pointermove', handleMove);
        window.addEventListener('pointerup', handleUp);
        window.addEventListener('pointercancel', handleUp);

        return () => {
            window.removeEventListener('pointermove', handleMove);
            window.removeEventListener('pointerup', handleUp);
            window.removeEventListener('pointercancel', handleUp);
            // Ensure cleanup if component unmounts mid-drag
            document.body.classList.remove('no-scroll');
        };
    }, [dragState, inspect, onAdd, onRemove]);

    return {
        dragState,
        handlePointerDown
    };
};

