// Added React import to resolve namespace error for React.PointerEvent
import React, { useState, useCallback, useRef, useEffect } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
    card: CardDefinition;
    origin: 'archive' | 'vault';
    startPos: { x: number; y: number };
    currentPos: { x: number; y: number };
    offset: { x: number; y: number };
    rect: DOMRect;
    active: boolean;
}

interface UseCollectionDragProps {
    onAdd: (id: string) => void;
    onRemove: (id: string) => void;
}

export const useCollectionDrag = ({ onAdd, onRemove }: UseCollectionDragProps) => {
    const { inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    const gesture = useRef<{
        pointerId: number | null;
        timer: number | null;
        startTime: number;
        startPos: { x: number; y: number };
        isScrolling: boolean;
        isDragging: boolean;
        card: CardDefinition | null;
        origin: 'archive' | 'vault' | null;
        target: HTMLElement | null;
    }>({
        pointerId: null,
        timer: null,
        startTime: 0,
        startPos: { x: 0, y: 0 },
        isScrolling: false,
        isDragging: false,
        card: null,
        origin: null,
        target: null,
    });

    const cleanup = useCallback(() => {
        if (gesture.current.timer) {
            clearTimeout(gesture.current.timer);
        }
        if (gesture.current.isDragging) {
            document.body.classList.remove('no-scroll');
        }
        gesture.current.pointerId = null;
        gesture.current.isDragging = false;
        setDragState(null);
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent,
        card: CardDefinition,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0 || gesture.current.pointerId !== null) return;

        // CRITICAL FIX: Claim the event immediately. This stops the browser's
        // native edge-gestures (like 'swipe to go back') from hijacking the event,
        // which was causing inconsistent behavior at the screen edges.
        e.preventDefault();

        // Target must be captured before the event object is potentially reused.
        const target = e.currentTarget as HTMLElement;

        gesture.current = {
            pointerId: e.pointerId,
            card,
            origin,
            target: target,
            startTime: Date.now(),
            startPos: { x: e.clientX, y: e.clientY },
            isScrolling: false,
            isDragging: false,
            timer: window.setTimeout(() => {
                // Timer fired: If we haven't started scrolling, this is a drag.
                if (!gesture.current.isScrolling) {
                    gesture.current.isDragging = true;
                    document.body.classList.add('no-scroll');

                    const rect = gesture.current.target!.getBoundingClientRect();
                    setDragState({
                        card: gesture.current.card!,
                        origin: gesture.current.origin!,
                        active: true,
                        startPos: gesture.current.startPos,
                        currentPos: gesture.current.startPos,
                        rect,
                        offset: { 
                            x: gesture.current.startPos.x - rect.left, 
                            y: gesture.current.startPos.y - rect.top 
                        },
                    });
                }
                gesture.current.timer = null;
            }, 500) // 0.5 second threshold for long-press
        };
    }, []);

    useEffect(() => {
        const handlePointerMove = (e: PointerEvent) => {
            if (e.pointerId !== gesture.current.pointerId) return;

            // If drag is active, just update the card position.
            if (gesture.current.isDragging) {
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
                return;
            }

            // If a timer is pending, check for a scroll gesture.
            if (gesture.current.timer) {
                const dx = e.clientX - gesture.current.startPos.x;
                const dy = e.clientY - gesture.current.startPos.y;
                // A gesture is considered scrolling only if it's primarily vertical.
                // This prevents diagonal drags from being misidentified as scrolls.
                if (Math.abs(dy) > 10 && Math.abs(dy) > Math.abs(dx) * 2) { 
                    gesture.current.isScrolling = true;
                    clearTimeout(gesture.current.timer);
                    gesture.current.timer = null;
                }
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (e.pointerId !== gesture.current.pointerId) return;

            // Always clear a pending timer on release.
            if (gesture.current.timer) {
                clearTimeout(gesture.current.timer);
            }

            if (gesture.current.isDragging && dragState) {
                // --- HANDLE DROP ---
                const elements = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = elements.find(el => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = elements.find(el => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !vaultZone)) {
                    onRemove(dragState.card.id);
                }
            } else if (!gesture.current.isScrolling) {
                // --- HANDLE TAP ---
                // If it wasn't a drag and wasn't a scroll, it was a tap.
                const duration = Date.now() - gesture.current.startTime;
                const dist = Math.hypot(e.clientX - gesture.current.startPos.x, e.clientY - gesture.current.startPos.y);

                if (duration < 500 && dist < 10 && gesture.current.card) {
                    inspect(gesture.current.card);
                }
            }

            // --- CLEANUP ---
            cleanup();
        };

        window.addEventListener('pointermove', handlePointerMove);
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
        };
    }, [dragState, inspect, onAdd, onRemove, cleanup]);

    return {
        dragState,
        handlePointerDown
    };
};

