import React, { useState, useCallback, useRef, useEffect } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
    card: CardDefinition;
    origin: 'archive' | 'vault';
    startPos: { x: number; y: number };
    currentPos: { x: number; y: number };
    offset: { x: number; y: number };
    rect: DOMRect;
    active: boolean;
}

interface UseCollectionDragProps {
    onAdd: (id: string) => void;
    onRemove: (id: string) => void;
}

export const useCollectionDrag = ({ onAdd, onRemove }: UseCollectionDragProps) => {
    const { inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    const gesture = useRef<{
        pointerId: number | null;
        timer: number | null;
        startTime: number;
        startPos: { x: number; y: number };
        isDragging: boolean;
        card: CardDefinition | null;
        origin: 'archive' | 'vault' | null;
        target: HTMLElement | null;
    }>({
        pointerId: null,
        timer: null,
        startTime: 0,
        startPos: { x: 0, y: 0 },
        isDragging: false,
        card: null,
        origin: null,
        target: null,
    });

    const startDrag = useCallback((e: PointerEvent | React.PointerEvent) => {
        const g = gesture.current;
        if (g.isDragging || !g.target || !g.card || !g.origin) return;

        if (g.timer) {
            clearTimeout(g.timer);
            g.timer = null;
        }

        g.isDragging = true;
        document.body.classList.add('no-scroll');

        const rect = g.target.getBoundingClientRect();
        setDragState({
            card: g.card,
            origin: g.origin,
            active: true,
            startPos: g.startPos,
            currentPos: { x: e.clientX, y: e.clientY },
            rect,
            offset: { 
                x: g.startPos.x - rect.left, 
                y: g.startPos.y - rect.top 
            },
        });
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent,
        card: CardDefinition,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0 || gesture.current.pointerId !== null) return;

        e.preventDefault();
        const target = e.currentTarget as HTMLElement;
        target.setPointerCapture(e.pointerId);

        gesture.current = {
            pointerId: e.pointerId,
            card,
            origin,
            target,
            startTime: Date.now(),
            startPos: { x: e.clientX, y: e.clientY },
            isDragging: false,
            timer: window.setTimeout(() => {
                // Timer fired: If we haven't started dragging via movement, this is a long-press. Start drag now.
                startDrag(e);
            }, 200) // 0.2 second threshold for long-press
        };
    }, [startDrag]);

    useEffect(() => {
        const handlePointerMove = (e: PointerEvent) => {
            if (e.pointerId !== gesture.current.pointerId) return;

            if (gesture.current.isDragging) {
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
                return;
            }

            // If a gesture is active but not yet dragging, check for movement threshold.
            if (gesture.current.pointerId !== null) {
                const dist = Math.hypot(e.clientX - gesture.current.startPos.x, e.clientY - gesture.current.startPos.y);
                if (dist > 10) {
                    startDrag(e);
                }
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (e.pointerId !== gesture.current.pointerId) return;

            gesture.current.target?.releasePointerCapture(e.pointerId);

            if (gesture.current.timer) clearTimeout(gesture.current.timer);

            if (gesture.current.isDragging && dragState) {
                // --- HANDLE DROP ---
                const elements = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = elements.find(el => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = elements.find(el => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !vaultZone)) {
                    onRemove(dragState.card.id);
                }
            } else {
                // --- HANDLE TAP ---
                const dist = Math.hypot(e.clientX - gesture.current.startPos.x, e.clientY - gesture.current.startPos.y);
                if (dist < 10 && gesture.current.card) {
                    inspect(gesture.current.card);
                }
            }

            // --- CLEANUP ---
            document.body.classList.remove('no-scroll');
            setDragState(null);
            gesture.current.pointerId = null;
            gesture.current.isDragging = false;
        };

        const handlePointerCancel = (e: PointerEvent) => {
            if (e.pointerId !== gesture.current.pointerId) return;
            handlePointerUp(e); // Run the same cleanup logic
        };

        window.addEventListener('pointermove', handlePointerMove);
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerCancel);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerCancel);
        };
    }, [dragState, inspect, onAdd, onRemove, startDrag]);

    return {
        dragState,
        handlePointerDown
    };
};

