import React, { useCallback, useEffect, useRef, useState } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;

  /**
   * IMPORTANT: pass a ref to the actual scrollable element:
   * the <div className="flex-1 overflow-y-auto ..."> in CollectionGrid.
   */
  scrollContainerRef?: React.RefObject<HTMLElement>;
}

type Gesture = {
  pointerId: number | null;
  target: HTMLElement | null;
  card: CardDefinition | null;
  origin: 'archive' | 'vault' | null;
  startX: number;
  startY: number;
  isDragging: boolean;
  lockedScroll: boolean;
  prevOverflowY: string;
  prevTouchAction: string;
};

const DRAG_SLOP_PX = 6;

export const useCollectionDrag = ({ onAdd, onRemove, scrollContainerRef }: UseCollectionDragProps) => {
  const { inspect } = useUser();
  const [dragState, setDragState] = useState<CollectionDragState | null>(null);

  const gRef = useRef<Gesture>({
    pointerId: null,
    target: null,
    card: null,
    origin: null,
    startX: 0,
    startY: 0,
    isDragging: false,
    lockedScroll: false,
    prevOverflowY: '',
    prevTouchAction: '',
  });

  const lockScroll = useCallback(() => {
    const g = gRef.current;
    if (g.lockedScroll) return;

    const el = scrollContainerRef?.current;
    if (!el) return;

    g.prevOverflowY = el.style.overflowY;
    g.prevTouchAction = el.style.touchAction;

    // Prevent scrolling the grid while dragging (extra safety)
    el.style.overflowY = 'hidden';
    el.style.touchAction = 'none';

    g.lockedScroll = true;
  }, [scrollContainerRef]);

  const unlockScroll = useCallback(() => {
    const g = gRef.current;
    if (!g.lockedScroll) return;

    const el = scrollContainerRef?.current;
    if (el) {
      el.style.overflowY = g.prevOverflowY;
      el.style.touchAction = g.prevTouchAction;
    }

    g.lockedScroll = false;
    g.prevOverflowY = '';
    g.prevTouchAction = '';
  }, [scrollContainerRef]);

  const beginDrag = useCallback((e: PointerEvent) => {
    const g = gRef.current;
    if (g.isDragging || !g.target || !g.card || !g.origin) return;

    g.isDragging = true;
    lockScroll();

    const rect = g.target.getBoundingClientRect();
    const offsetX = g.startX - rect.left;
    const offsetY = g.startY - rect.top;

    setDragState({
      card: g.card,
      origin: g.origin,
      active: true,
      startPos: { x: g.startX, y: g.startY },
      currentPos: { x: e.clientX, y: e.clientY },
      rect,
      offset: { x: offsetX, y: offsetY },
    });
  }, [lockScroll]);

  const handlePointerDown = useCallback(
    (e: React.PointerEvent, card: CardDefinition, origin: 'archive' | 'vault') => {
      // Only primary touch / left mouse
      if (!e.isPrimary) return;
      if (e.button !== 0) return;

      const g = gRef.current;
      if (g.pointerId !== null) return;

      const target = e.currentTarget as HTMLElement;

      // Capture the pointer so moves/up still arrive even if finger leaves the element
      target.setPointerCapture(e.pointerId);

      // NOTE: The *real* scroll prevention is CSS touch-action on the card.
      // Still prevent default to avoid things like text selection / ghost behaviors.
      e.preventDefault();

      g.pointerId = e.pointerId;
      g.target = target;
      g.card = card;
      g.origin = origin;
      g.startX = e.clientX;
      g.startY = e.clientY;
      g.isDragging = false;
    },
    []
  );

  useEffect(() => {
    const onMove = (e: PointerEvent) => {
      const g = gRef.current;
      if (g.pointerId === null || e.pointerId !== g.pointerId) return;

      if (g.isDragging) {
        setDragState((prev) =>
          prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : prev
        );
        return;
      }

      // Slop check: only start drag after slight movement to avoid accidental taps.
      const dx = e.clientX - g.startX;
      const dy = e.clientY - g.startY;
      if (Math.hypot(dx, dy) >= DRAG_SLOP_PX) {
        beginDrag(e);
      }
    };

    const finish = (e: PointerEvent, cancelled: boolean) => {
      const g = gRef.current;
      if (g.pointerId === null || e.pointerId !== g.pointerId) return;

      // Release capture safely
      try {
        g.target?.releasePointerCapture(e.pointerId);
      } catch {
        // ignore
      }

      if (g.isDragging && dragState && !cancelled) {
        const elements = document.elementsFromPoint(e.clientX, e.clientY);
        const vaultZone = elements.find((el) => el.getAttribute('data-drop-zone') === 'vault');
        const archiveZone = elements.find((el) => el.getAttribute('data-drop-zone') === 'archive');

        if (dragState.origin === 'archive' && vaultZone) {
          onAdd(dragState.card.id);
        } else if (dragState.origin === 'vault' && (archiveZone || !vaultZone)) {
          onRemove(dragState.card.id);
        }
      } else if (!g.isDragging && !cancelled && g.card) {
        // Tap (no drag)
        const dx = e.clientX - g.startX;
        const dy = e.clientY - g.startY;
        if (Math.hypot(dx, dy) < DRAG_SLOP_PX) {
          inspect(g.card);
        }
      }

      // Cleanup
      unlockScroll();
      setDragState(null);

      g.pointerId = null;
      g.target = null;
      g.card = null;
      g.origin = null;
      g.isDragging = false;
    };

    const onUp = (e: PointerEvent) => finish(e, false);
    const onCancel = (e: PointerEvent) => finish(e, true);

    // Use capture so you see events early; no reliance on passive touchmove hacks.
    window.addEventListener('pointermove', onMove, { capture: true });
    window.addEventListener('pointerup', onUp, { capture: true });
    window.addEventListener('pointercancel', onCancel, { capture: true });

    return () => {
      window.removeEventListener('pointermove', onMove, { capture: true } as any);
      window.removeEventListener('pointerup', onUp, { capture: true } as any);
      window.removeEventListener('pointercancel', onCancel, { capture: true } as any);
    };
  }, [beginDrag, dragState, inspect, onAdd, onRemove, unlockScroll, unlockScroll]);

  return { dragState, handlePointerDown };
};

> Note: there’s a tiny TS annoyance removing listeners with {capture:true}; the as any keeps it simple. If you prefer, define a constant const opts = {capture:true} as const; and reuse the same object reference.




