/**
 * useCollectionDrag.ts
 *
 * Mobile-first “Snap-like” gesture arbitration for a dense, scrollable card grid:
 * - Fast movement => SCROLL (native scroll wins)
 * - Short hold (long-press) => DRAG (scroll hard-disabled until release)
 * - Quick tap (no meaningful move) => INSPECT
 *
 * Requirements covered:
 * ✅ Tap to inspect
 * ✅ Reliable scroll vs drag intent (no “dead-space scroll” needed)
 * ✅ Scroll disabled only after drag is committed
 * ✅ Clean listener & style cleanup on pointerup/cancel
 * ✅ No async usage of React synthetic events (we only store primitives)
 *
 * Integration requirements:
 * - Provide scrollRef pointing to the actual overflow-y container.
 * - DO NOT set touch-action:none on card; allow pan-y so scrolling can begin on cards.
 *   Recommended CSS:
 *     Scroll container: touch-action: pan-y;
 *     Card wrappers:    touch-action: pan-y;
 */

import React, { useCallback, useEffect, useRef, useState } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;

  /**
   * REQUIRED: ref to the actual scrollable element:
   * the <div className="flex-1 overflow-y-auto ..."> in CollectionGrid.
   */
  scrollRef: React.RefObject<HTMLElement>;
}

type Phase = 'idle' | 'pending' | 'dragging' | 'scrolling';

const LONG_PRESS_MS = 150;       // tweak 120–180ms
const TAP_MAX_MS = 250;          // quick tap cutoff
const MOVE_JITTER_PX = 6;        // ignore tiny jitter
const SCROLL_INTENT_PX = 10;     // movement before long-press => treat as scroll
const TAP_MAX_MOVE_PX = 8;       // max movement allowed for tap inspect

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef }: UseCollectionDragProps) => {
  const { inspect } = useUser();
  const [dragState, setDragState] = useState<CollectionDragState | null>(null);

  const g = useRef({
    phase: 'idle' as Phase,
    pointerId: -1,
    startX: 0,
    startY: 0,
    startTime: 0,
    lastX: 0,
    lastY: 0,
    card: null as CardDefinition | null,
    origin: null as 'archive' | 'vault' | null,
    target: null as HTMLElement | null,
    timer: 0 as number | 0,
    // scroll lock bookkeeping
    prevOverflowY: '',
    prevTouchAction: '',
    touchMoveHandler: null as ((e: TouchEvent) => void) | null,
  });

  const clearTimer = useCallback(() => {
    if (g.current.timer) {
      window.clearTimeout(g.current.timer);
      g.current.timer = 0;
    }
  }, []);

  /**
   * Hard-disable scroll ONLY after we commit to dragging.
   * Includes iOS-specific touchmove preventDefault (passive:false).
   */
  const lockScroll = useCallback(() => {
    const scroller = scrollRef.current;
    if (!scroller) return;

    g.current.prevOverflowY = scroller.style.overflowY;
    g.current.prevTouchAction = scroller.style.touchAction;

    // CSS lock
    scroller.style.overflowY = 'hidden';
    scroller.style.touchAction = 'none';

    // iOS belt-and-suspenders: prevent touchmove while dragging
    const onTouchMove = (e: TouchEvent) => {
      if (g.current.phase === 'dragging') e.preventDefault();
    };
    g.current.touchMoveHandler = onTouchMove;
    scroller.addEventListener('touchmove', onTouchMove, { passive: false });
  }, [scrollRef]);

  const unlockScroll = useCallback(() => {
    const scroller = scrollRef.current;
    if (!scroller) return;

    scroller.style.overflowY = g.current.prevOverflowY;
    scroller.style.touchAction = g.current.prevTouchAction;

    if (g.current.touchMoveHandler) {
      scroller.removeEventListener('touchmove', g.current.touchMoveHandler as any);
      g.current.touchMoveHandler = null;
    }

    g.current.prevOverflowY = '';
    g.current.prevTouchAction = '';
  }, [scrollRef]);

  const beginDrag = useCallback(
    (clientX: number, clientY: number) => {
      const st = g.current;
      if (st.phase === 'dragging') return;
      if (!st.target || !st.card || !st.origin) return;

      st.phase = 'dragging';
      lockScroll();

      const rect = st.target.getBoundingClientRect();
      setDragState({
        card: st.card,
        origin: st.origin,
        active: true,
        startPos: { x: st.startX, y: st.startY },
        currentPos: { x: clientX, y: clientY },
        rect,
        offset: { x: st.startX - rect.left, y: st.startY - rect.top },
      });
    },
    [lockScroll]
  );

  const resetGesture = useCallback(() => {
    clearTimer();
    unlockScroll();
    setDragState(null);

    g.current.phase = 'idle';
    g.current.pointerId = -1;
    g.current.card = null;
    g.current.origin = null;
    g.current.target = null;
    g.current.startTime = 0;
  }, [clearTimer, unlockScroll]);

  /**
   * Attach to each draggable card wrapper.
   * NOTE: Do NOT use the event object asynchronously. We only store primitives.
   */
  const handlePointerDown = useCallback(
    (e: React.PointerEvent, card: CardDefinition, origin: 'archive' | 'vault') => {
      if (!e.isPrimary) return;
      if (e.button !== 0) return;
      if (g.current.phase !== 'idle') return;

      const target = e.currentTarget as HTMLElement;

      // Pointer capture so we keep receiving move/up even if finger leaves element.
      target.setPointerCapture(e.pointerId);

      g.current.phase = 'pending';
      g.current.pointerId = e.pointerId;
      g.current.startX = e.clientX;
      g.current.startY = e.clientY;
      g.current.lastX = e.clientX;
      g.current.lastY = e.clientY;
      g.current.startTime = performance.now();
      g.current.card = card;
      g.current.origin = origin;
      g.current.target = target;

      // Long-press => commit to drag
      clearTimer();
      g.current.timer = window.setTimeout(() => {
        if (g.current.phase === 'pending') {
          beginDrag(g.current.lastX, g.current.lastY);
        }
      }, LONG_PRESS_MS);
    },
    [beginDrag, clearTimer]
  );

  useEffect(() => {
    const onPointerMove = (e: PointerEvent) => {
      const st = g.current;
      if (e.pointerId !== st.pointerId) return;

      st.lastX = e.clientX;
      st.lastY = e.clientY;

      const dx = e.clientX - st.startX;
      const dy = e.clientY - st.startY;
      const dist = Math.hypot(dx, dy);

      if (st.phase === 'dragging') {
        setDragState((prev) =>
          prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : prev
        );
        return;
      }

      if (st.phase === 'pending') {
        // Ignore tiny jitter
        if (dist < MOVE_JITTER_PX) return;

        // If user moves meaningfully BEFORE long-press, treat as scroll intent.
        // We intentionally yield to native scroll.
        if (dist >= SCROLL_INTENT_PX) {
          st.phase = 'scrolling';
          clearTimer();

          // Release capture so browser can pan-scroll naturally.
          try {
            st.target?.releasePointerCapture(st.pointerId);
          } catch {
            // ignore
          }
          return;
        }
      }
    };

    const finish = (e: PointerEvent, cancelled: boolean) => {
      const st = g.current;
      if (e.pointerId !== st.pointerId) return;

      clearTimer();

      // Release capture safely
      try {
        st.target?.releasePointerCapture(st.pointerId);
      } catch {
        // ignore
      }

      const elapsed = performance.now() - st.startTime;
      const dx = e.clientX - st.startX;
      const dy = e.clientY - st.startY;
      const dist = Math.hypot(dx, dy);

      // DRAG DROP
      if (st.phase === 'dragging' && dragState && !cancelled) {
        const els = document.elementsFromPoint(e.clientX, e.clientY);
        const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
        const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

        if (dragState.origin === 'archive' && vaultZone) {
          onAdd(dragState.card.id);
        } else if (dragState.origin === 'vault' && (archiveZone || !vaultZone)) {
          onRemove(dragState.card.id);
        }

        resetGesture();
        return;
      }

      // SCROLLING: do nothing (native scroll already happened)
      if (st.phase === 'scrolling') {
        resetGesture();
        return;
      }

      // TAP INSPECT
      // - must still be pending (never dragged, never scrolled)
      // - must be quick enough
      // - must not move too much
      if (!cancelled && st.phase === 'pending' && st.card) {
        if (elapsed <= TAP_MAX_MS && dist <= TAP_MAX_MOVE_PX) {
          inspect(st.card);
        }
      }

      resetGesture();
    };

    const onPointerUp = (e: PointerEvent) => finish(e, false);
    const onPointerCancel = (e: PointerEvent) => finish(e, true);

    window.addEventListener('pointermove', onPointerMove, { capture: true });
    window.addEventListener('pointerup', onPointerUp, { capture: true });
    window.addEventListener('pointercancel', onPointerCancel, { capture: true });

    return () => {
      window.removeEventListener('pointermove', onPointerMove, { capture: true } as any);
      window.removeEventListener('pointerup', onPointerUp, { capture: true } as any);
      window.removeEventListener('pointercancel', onPointerCancel, { capture: true } as any);
    };
  }, [clearTimer, dragState, inspect, onAdd, onRemove, resetGesture]);

  return { dragState, handlePointerDown };
};

