                                    className={`px-2 py-2 border rounded text-[0.7rem] font-black transition-colors text-center uppercase tracking-tighter ${isActive ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-slate-700/50 border-slate-600 text-slate-300 hover:bg-slate-700'}`}
                                >
                                    {label}
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Click Outside Overlay */}
            {(showSortMenu || showFilterMenu) && (
                <div className="fixed inset-0 z-40" onClick={() => { setShowSortMenu(false); setShowFilterMenu(false); }}></div>
            )}

            {/* SORT BUTTON (Left) - Icon Only */}
            <button 
                onClick={() => { setShowSortMenu(!showSortMenu); setShowFilterMenu(false); }}
                className={`w-11 h-11 flex items-center justify-center bg-slate-800/90 backdrop-blur border rounded-lg active:scale-95 transition-all shadow-lg ${showSortMenu ? 'border-indigo-500 text-indigo-400' : 'border-slate-600 text-slate-300'}`}
            >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4h13M3 8h9m-9 4h6m4 0l4-4m0 0l4 4m-4-4v12" /></svg>
            </button>

            {/* FILTER BUTTON (Right) - Icon Only */}
            <button 
                 onClick={() => { setShowFilterMenu(!showFilterMenu); setShowSortMenu(false); }}
                 className={`w-11 h-11 flex items-center justify-center bg-slate-800/90 backdrop-blur border rounded-lg active:scale-95 transition-all shadow-lg ${showFilterMenu ? 'border-indigo-500 text-indigo-400' : 'border-slate-600 text-slate-300'}`}
            >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6-414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" /></svg>
            </button>

        </div>
    );
};

